export const TECH_MONOGRAMS = {
  go: "Go",
  ts: "TS",
  python: "Py",
  sql: "SQL",
  grpc: "gRPC",
  fastapi: "Fast",
  nodejs: "Node",
  microservices: "Mesh",
  postgres: "PG",
  timescale: "TS",
  qdrant: "Qdrant",
  redis: "Redis",
  kafka: "Kafka",
  rabbitmq: "Rabbit",
  docker: "Docker",
  k8s: "K8s",
  linux: "Linux",
  prometheus: "Prom",
  grafana: "GFN",
  "ai-rag": "RAG",
  git: "Git",
  vite: "Vite",
  react: "React",
  vue: "Vue",
  mysql: "SQL",
  mongodb: "MDB",
  php: "PHP",
  cloudflare: "CF",
  aws: "AWS"
};

/**
 * Get SVG string for a given tech key or default fallback
 */
export function getTechIconSvg(iconKey) {
  if (!iconKey) return TECH_ICONS.sql;
  const key = iconKey.toLowerCase().trim();
  return TECH_ICONS[key] || TECH_ICONS.sql;
}

/**
 * Get 2-4 letter monogram fallback
 */
export function getTechMonogram(iconKey) {
  if (!iconKey) return "SYS";
  const key = iconKey.toLowerCase().trim();
  return TECH_MONOGRAMS[key] || key.slice(0, 3).toUpperCase();
}

/**
 * Creates an Image object with valid SVG data URL for HTML5 Canvas rendering
 */
const canvasImageCache = new Map();

export function getTechIconCanvasImage(iconKey) {
  if (!iconKey) iconKey = "sql";
  const key = iconKey.toLowerCase().trim();

  if (canvasImageCache.has(key)) {
    return canvasImageCache.get(key);
  }

  const svgStr = TECH_ICONS[key] || TECH_ICONS.sql;
  const img = new Image();
  // Safe btoa base64 data url for 100% reliable cross-browser SVG decoding
  try {
    const b64 = btoa(unescape(encodeURIComponent(svgStr)));
    img.src = `data:image/svg+xml;base64,${b64}`;
  } catch (e) {
    img.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgStr)}`;
  }
  
  canvasImageCache.set(key, img);
  return img;
}
